        if (!mem.eql(u8, issue.rule, RULE_DEFINITE_ASSIGNMENT)) continue;
        try std.testing.expectEqual(@as(usize, 6), issue.line);
        try std.testing.expect(mem.indexOf(u8, issue.message, "'x'") != null);
        found = true;
    }
    try std.testing.expect(found);
}

