// Update Check Tests
// ============================================================================

test "isNewerVersion detects newer versions" {
    try std.testing.expect(isNewerVersion("0.7.4", "0.8.0"));
    try std.testing.expect(isNewerVersion("0.7.4", "0.7.5"));
    try std.testing.expect(isNewerVersion("0.7.4", "1.0.0"));
    try std.testing.expect(!isNewerVersion("0.7.4", "0.7.4"));
    try std.testing.expect(!isNewerVersion("0.7.4", "0.7.3"));
    try std.testing.expect(!isNewerVersion("0.7.4", "0.6.9"));
    try std.testing.expect(!isNewerVersion("1.0.0", "0.99.99"));
}

test "isNewerVersion handles dev suffix" {
    try std.testing.expect(isNewerVersion("0.7.4", "0.8.0-dev"));
    try std.testing.expect(!isNewerVersion("0.8.0", "0.8.0-dev"));
}

test "parseSemver parses valid versions" {
    const v = parseSemver("1.2.3").?;
    try std.testing.expectEqual(@as(u32, 1), v[0]);
    try std.testing.expectEqual(@as(u32, 2), v[1]);
    try std.testing.expectEqual(@as(u32, 3), v[2]);
}

test "parseSemver rejects invalid versions" {
    try std.testing.expect(parseSemver("abc") == null);
    try std.testing.expect(parseSemver("1.2") == null);
    try std.testing.expect(parseSemver("") == null);
}

test "parseVersionFromZon extracts version" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const zon_content =
        \\.{
        \\    .name = .ephor,
        \\    .version = "0.9.0",
        \\    .fingerprint = 0x12345,
        \\}
    ;

    const ver = parseVersionFromZon(allocator, zon_content).?;
    defer allocator.free(ver);
    try std.testing.expectEqualStrings("0.9.0", ver);
}

test "parseVersionFromZon returns null for missing version" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const bad_content = ".{ .name = .ephor }";
    try std.testing.expect(parseVersionFromZon(allocator, bad_content) == null);
}

// --- Update cache test seam ---
// resolveLatestVersion takes the fetcher as a function pointer so tests can
// count calls and control the result without touching the network.
var test_fetch_calls: usize = 0;
var test_fetch_result: ?[]const u8 = null;

fn testFetchFn(allocator: Allocator) ?[]const u8 {
    test_fetch_calls += 1;
    const v = test_fetch_result orelse return null;
    return allocator.dupe(u8, v) catch null;
}

fn resetFetchSeam(result: ?[]const u8) void {
    test_fetch_calls = 0;
    test_fetch_result = result;
}

/// Absolute path of `name` inside the tmp dir (the cache fns are path-based).
fn tmpFilePath(allocator: Allocator, tmp: *std.testing.TmpDir, name: []const u8) ![]const u8 {
    const dir_path = try tmp.dir.realPathFileAlloc(std.testing.io, ".", allocator);
    defer allocator.free(dir_path);
    return std.fs.path.join(allocator, &.{ dir_path, name });
}

test "updateCheckDisabled is presence-only" {
    try std.testing.expect(!updateCheckDisabled(null));
    try std.testing.expect(updateCheckDisabled(""));
    try std.testing.expect(updateCheckDisabled("0"));
    try std.testing.expect(updateCheckDisabled("1"));
}

test "isCacheFresh boundary and fail-closed cases" {
    const now: i64 = 1_800_000_000;
    try std.testing.expect(isCacheFresh(now, now));
    try std.testing.expect(isCacheFresh(now - UPDATE_CACHE_MAX_AGE_S + 1, now));
    // Exactly 24h old is stale (pinned boundary).
    try std.testing.expect(!isCacheFresh(now - UPDATE_CACHE_MAX_AGE_S, now));
    try std.testing.expect(!isCacheFresh(-1, now));
    // Future epochs: tolerated inside the skew window, stale beyond it.
    try std.testing.expect(isCacheFresh(now + UPDATE_CACHE_FUTURE_SKEW_S, now));
    try std.testing.expect(!isCacheFresh(now + UPDATE_CACHE_FUTURE_SKEW_S + 1, now));
}

test "resolveUpdateCachePath requires HOME" {
    const allocator = std.testing.allocator;
    try std.testing.expect(resolveUpdateCachePath(allocator, null) == null);
    try std.testing.expect(resolveUpdateCachePath(allocator, "") == null);
    const path = resolveUpdateCachePath(allocator, "/home/dev") orelse
        return error.TestUnexpectedResult;
    defer allocator.free(path);
    try std.testing.expectEqualStrings("/home/dev/.ephor_update_check", path);
}

test "update cache write/read round-trip" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);

    const now: i64 = 1_800_000_000;
    writeUpdateCache(allocator, path, "1.2.3", now);

    const cached = readUpdateCache(allocator, path) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(cached.version);
    try std.testing.expectEqualStrings("1.2.3", cached.version);
    try std.testing.expectEqual(now, cached.epoch);
}

test "resolveLatestVersion returns fresh cache without fetching" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;
    writeUpdateCache(allocator, path, "1.2.3", now - 60);

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("1.2.3", latest);
    try std.testing.expectEqual(@as(usize, 0), test_fetch_calls);
}

test "resolveLatestVersion refetches stale cache and rewrites it" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;
    writeUpdateCache(allocator, path, "1.2.3", now - UPDATE_CACHE_MAX_AGE_S);

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("9.9.9", latest);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);

    // Cache rewritten with the fetched version, stamped with the injected now.
    const cached = readUpdateCache(allocator, path) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(cached.version);
    try std.testing.expectEqualStrings("9.9.9", cached.version);
    try std.testing.expectEqual(now, cached.epoch);

    // A second resolve now hits the fresh cache — no additional fetch.
    const again = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(again);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);
}

test "resolveLatestVersion treats future-dated cache as stale" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;
    writeUpdateCache(allocator, path, "1.2.3", now + UPDATE_CACHE_FUTURE_SKEW_S + 1);

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("9.9.9", latest);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);
}

test "resolveLatestVersion refetches corrupt cache" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "cache",
        .data = "garbage\nnotsemver\n",
    });

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("9.9.9", latest);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);

    // Corrupt content replaced by a valid cache entry.
    const cached = readUpdateCache(allocator, path) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(cached.version);
    try std.testing.expectEqualStrings("9.9.9", cached.version);
}

test "resolveLatestVersion fetches when cache file is missing" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, path, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("9.9.9", latest);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);

    // Fetch success creates the cache file.
    const cached = readUpdateCache(allocator, path) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(cached.version);
    try std.testing.expectEqualStrings("9.9.9", cached.version);
}

test "resolveLatestVersion leaves cache untouched on fetch failure" {
    global_io = std.testing.io;
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try tmpFilePath(allocator, &tmp, "cache");
    defer allocator.free(path);
    const now: i64 = 1_800_000_000;
    const original = "123\n1.2.3\n";
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "cache", .data = original });

    resetFetchSeam(null);
    const result = resolveLatestVersion(allocator, path, now, testFetchFn);
    try std.testing.expect(result == null);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);

    // Failed fetch must not rewrite the file — bytes identical to before.
    const raw = try tmp.dir.readFileAlloc(
        std.testing.io,
        "cache",
        allocator,
        .limited(4096),
    );
    defer allocator.free(raw);
    try std.testing.expectEqualStrings(original, raw);
}

test "resolveLatestVersion without cache path always fetches" {
    const allocator = std.testing.allocator;
    const now: i64 = 1_800_000_000;

    resetFetchSeam("9.9.9");
    const latest = resolveLatestVersion(allocator, null, now, testFetchFn) orelse
        return error.TestUnexpectedResult;
    defer allocator.free(latest);
    try std.testing.expectEqualStrings("9.9.9", latest);
    try std.testing.expectEqual(@as(usize, 1), test_fetch_calls);
}

// ============================================================================
// Config Migration Tests (migrateThresholds / buildMissingKeysJson)
// ============================================================================

const MigrateInsertCase = struct {
    name: []const u8,
    input: []const u8,
    expected: []const u8,
};

const MigrateNullCase = struct {
    name: []const u8,
    input: []const u8,
};

const MissingKeysCase = struct {
    name: []const u8,
    mig: MissingThresholdKeys,
    expected: []const u8,
};

/// Characterization pins: byte-exact migration output per case.
const migrate_insert_cases = [_]MigrateInsertCase{
    .{
        .name = "only max_cyclomatic missing inserts only cyclo",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cognitive": 12
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_cognitive": 12,
        \\    "max_cyclomatic": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "only max_cognitive missing inserts only cog, value 99 preserved",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 99
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 99,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "neither key present inserts both, cyclo then cog",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 15,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "trailing comma in body gets no leading comma on insert",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\  }
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\    "max_function_lines": 50,
        \\    "max_cyclomatic": 15,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "empty thresholds object fills at derived indent",
        .input =
        \\{
        \\  "thresholds": {}
        \\}
        ,
        .expected =
        \\{
        \\  "thresholds": {
        \\  "max_cyclomatic": 15,
        \\  "max_cognitive": 15
        \\}
        \\}
        ,
    },
    .{
        .name = "nested thresholds uses close_indent + 2 as entry indent",
        .input =
        \\{
        \\    "outer": {
        \\        "thresholds": {
        \\            "max_cyclomatic": 15
        \\        }
        \\    }
        \\}
        ,
        // Inserted entry lands at close_indent(8)+2=10 spaces, NOT aligned
        // with the sibling key at 12 — the algorithm derives indent from the
        // closing brace only. Valid JSON; cosmetic misalignment is the pin.
        .expected =
        \\{
        \\    "outer": {
        \\        "thresholds": {
        \\            "max_cyclomatic": 15,
        \\          "max_cognitive": 15
        \\        }
        \\    }
        \\}
        ,
    },
    .{
        .name = "disable array and content outside thresholds stay byte-identical",
        .input =
        \\{
        \\  "version": "0.13.0",
        \\  "disable": ["ZA305", "ZA306"],
        \\  "thresholds": {
        \\    "max_cyclomatic": 99
        \\  },
        \\  "strict": true
        \\}
        ,
        .expected =
        \\{
        \\  "version": "0.13.0",
        \\  "disable": ["ZA305", "ZA306"],
        \\  "thresholds": {
        \\    "max_cyclomatic": 99,
        \\    "max_cognitive": 15
        \\  },
        \\  "strict": true
        \\}
        ,
    },
};

const migrate_null_cases = [_]MigrateNullCase{
    .{
        .name = "both keys present is a no-op",
        .input =
        \\{
        \\  "thresholds": {
        \\    "max_cyclomatic": 15,
        \\    "max_cognitive": 15
        \\  }
        \\}
        ,
    },
    .{
        .name = "no thresholds key at all",
        .input =
        \\{
        \\  "version": "0.14.0"
        \\}
        ,
    },
    .{
        .name = "thresholds is not an object",
        .input = "{\"thresholds\": 5}",
    },
    .{
        .name = "empty content",
        .input = "",
    },
};

const missing_keys_cases = [_]MissingKeysCase{
    .{
        .name = "both missing with leading comma keeps entries order",
        .mig = .{
            .entry_indent = "    ",
            .needs_comma = true,
            .has_cyclo = false,
            .has_cog = false,
        },
        .expected =
        \\,
        \\    "max_cyclomatic": 15,
        \\    "max_cognitive": 15
        ,
    },
    .{
        .name = "only cognitive missing without comma emits single entry",
        .mig = .{
            .entry_indent = "    ",
            .needs_comma = false,
            .has_cyclo = true,
            .has_cog = false,
        },
        .expected =
        \\
        \\    "max_cognitive": 15
        ,
    },
    .{
        .name = "only cyclomatic missing without comma uses given indent",
        .mig = .{
            .entry_indent = "  ",
            .needs_comma = false,
            .has_cyclo = false,
            .has_cog = true,
        },
        .expected =
        \\
        \\  "max_cyclomatic": 15
        ,
    },
};

test "migrateThresholds inserts missing keys byte-exactly" {
    for (&migrate_insert_cases) |*case| {
        const maybe_actual = migrateThresholds(std.testing.allocator, case.input);
        if (maybe_actual == null) {
            std.debug.print("case '{s}': expected migration, got null\n", .{case.name});
        }
        try std.testing.expect(maybe_actual != null);
        defer std.testing.allocator.free(maybe_actual.?);
        std.testing.expectEqualStrings(case.expected, maybe_actual.?) catch {
            std.debug.print("case '{s}' failed\n", .{case.name});
            try std.testing.expect(false);
        };
    }
}

test "migrateThresholds returns null when nothing needs migration" {
    for (&migrate_null_cases) |*case| {
        if (migrateThresholds(std.testing.allocator, case.input)) |actual| {
            std.debug.print("case '{s}': expected null, got:\n{s}\n", .{ case.name, actual });
            std.testing.allocator.free(actual);
            try std.testing.expect(false);
        }
    }
}

test "buildMissingKeysJson serializes missing entries in order" {
    for (&missing_keys_cases) |*case| {
        const actual = try buildMissingKeysJson(std.testing.allocator, case.mig);
        defer std.testing.allocator.free(actual);
        std.testing.expectEqualStrings(case.expected, actual) catch {
            std.debug.print("case '{s}' failed\n", .{case.name});
            try std.testing.expect(false);
        };
    }
}

test "fnReturnsType detects literal type return" {
    // Returns type → TitleCase required
    try std.testing.expect(fnReturnsType("fn Point(T: type) type {", 8));
    try std.testing.expect(fnReturnsType("fn ShortList(comptime T: type, comptime n: usize) type {", 12));
    try std.testing.expect(fnReturnsType("pub fn MakeStruct(comptime T: type) type {", 12));
}

test "fnReturnsType detects error union type return" {
    // Returns !type → still TitleCase
    try std.testing.expect(fnReturnsType("fn MakeType(x: u32) !type {", 11));
}

test "fnReturnsType rejects non-type returns" {
    // Returns T, not type → camelCase
    try std.testing.expect(!fnReturnsType("fn foo(T: type) T {", 6));
    try std.testing.expect(!fnReturnsType("fn doubleIt(comptime T: type, value: T) T {", 11));
    try std.testing.expect(!fnReturnsType("fn init(allocator: std.mem.Allocator) !Self {", 7));
    try std.testing.expect(!fnReturnsType("fn parse() !void {", 8));
    try std.testing.expect(!fnReturnsType("fn getValue() u32 {", 11));
}

test "fnReturnsType handles nested fn type params" {
    // Inner fn returns type, but outer fn returns void → camelCase
    try std.testing.expect(!fnReturnsType("fn register(cb: fn(type) type, x: u32) void {", 11));
}

test "fnReturnsType rejects type-prefixed identifiers" {
    // "typedef" is not "type"
    try std.testing.expect(!fnReturnsType("fn foo() typedef {", 6));
}

test "checkVarNaming: fn-valued vars are still snake_case (declaration kind rules)" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();

    var issues: std.ArrayListUnmanaged(Issue) = .empty;
    defer deinitIssues(&issues, a);

    // Field access / method reference RHS is ambiguous — var kind decides.
    const mutex_line = "pub var group_storage_mutex = compat.Mutex.init;";
    try checkVarNaming(.{
        .issues = &issues,
        .allocator = a,
        .path = "test.zig",
        .t = mutex_line,
        .line_num = 1,
    });
    try checkVarNaming(.{
        .issues = &issues,
        .allocator = a,
        .path = "test.zig",
        .t = "var current_key = snapshot.key;",
        .line_num = 2,
    });
    try std.testing.expectEqual(@as(usize, 0), issues.items.len);
}

test "checkVarNaming: non-snake_case var is flagged" {
    var gpa = std.heap.DebugAllocator(.{}){};
    defer _ = gpa.deinit();
    const a = gpa.allocator();

    var issues: std.ArrayListUnmanaged(Issue) = .empty;
    defer deinitIssues(&issues, a);

    try checkVarNaming(.{
        .issues = &issues,
        .allocator = a,
        .path = "test.zig",
        .t = "var myBadVar = 5;",
        .line_num = 1,
    });
    try std.testing.expectEqual(@as(usize, 1), issues.items.len);
    try std.testing.expectEqualStrings(
        "variable 'myBadVar' should be snake_case",
        issues.items[0].message,
    );
}

// ============================================================================
// ZA703 Closure-Wrapper / Type-Definition Classification Tests
// ============================================================================

test "isTypeDefinition: real type defs detected" {
    const c1 = "const Foo = struct {};";
    try std.testing.expect(isTypeDefinition(c1, c1, 0));
    const c2 = "const Color = enum { red, green };";
    try std.testing.expect(isTypeDefinition(c2, c2, 0));
    const c3 = "const Tag = union { a: u32, b: u64 };";
    try std.testing.expect(isTypeDefinition(c3, c3, 0));
    const c4 = "const Bits = packed struct(u32) { a: u16, b: u16 };";
    try std.testing.expect(isTypeDefinition(c4, c4, 0));
}

test "isTypeDefinition: single-line closure NOT a type def" {
    const c = "const readBytes = struct { fn call() void {} }.call;";
    try std.testing.expect(!isTypeDefinition(c, c, 0));
}

test "isTypeDefinition: multi-line closure NOT a type def" {
    const content =
        "const readBytes = struct {\n" ++
        "    fn call() void {}\n" ++
        "}.call;\n";
    // First line is what the analyzer trims and passes as `t`.
    const line = "const readBytes = struct {";
    try std.testing.expect(!isTypeDefinition(line, content, 0));
}

test "isTypeDefinition: nested braces inside closure body still resolved correctly" {
    const content =
        "const wrap = struct {\n" ++
        "    fn call(a: u32) u32 {\n" ++
        "        if (a > 0) { return a; } else { return 0; }\n" ++
        "    }\n" ++
        "}.call;\n";
    const line = "const wrap = struct {";
    try std.testing.expect(!isTypeDefinition(line, content, 0));
}

test "isTypeDefinition: multi-line REAL type def still detected" {
    const content =
        "const Foo = struct {\n" ++
        "    field: u32,\n" ++
        "};\n";
    const line = "const Foo = struct {";
    try std.testing.expect(isTypeDefinition(line, content, 0));
}

test "isTypeDefinition: array literal of anonymous struct not a type def" {
    // `[_]struct { ... }{ ... }` has no space before `struct`, so the keyword
    // pattern ` struct` must NOT match.
    const c = "const keys = [_]struct { name: []const u8 }{ .{ .name = \"a\" } };";
    try std.testing.expect(!isTypeDefinition(c, c, 0));
}

test "isClosureFunctionAlias: detects multi-line closure" {
    const content =
        "const readBytes = struct {\n" ++
        "    fn call() void {}\n" ++
        "}.call;\n";
    const line = "const readBytes = struct {";
    try std.testing.expect(isClosureFunctionAlias(line, content, 0));
}

test "isClosureFunctionAlias: rejects real type def" {
    const c = "const Foo = struct { x: u32 };";
    try std.testing.expect(!isClosureFunctionAlias(c, c, 0));
}

