    const content =
        \\fn doWork() void {}
        \\fn f(x: u8, d: bool) void {
        \\    switch (x) {
        \\        0 => {
        \\            mu.lock();
        \\        },
        \\        else => {
        \\            doWork();
        \\        },
        \\    }
