        \\    return struct {
        \\        pub fn lockTwice(objs: *@This()) void {
        \\            objs.internal.mu.lock();
        \\            objs.internal.mu.lock();
        \\        }
        \\    };
        \\}
    ;
    var run = try runConcurrencyCheck(allocator, "zc102_nested.zig", content);
    defer run.deinit(allocator);

    try expectZC102Counts(run.issues.items, 1, 0);
}

