        \\    context.thread = try std.Thread.spawn(.{}, work, .{context});
        \\}
        \\fn deinit(self: *Context) void {
        \\    const thread = self.thread;
        \\    defer thread.join();
        \\    self.signal.stop();
        \\}
    ;
